/**
 * The notice that belongs to the application frame and stays until its cause ends (`design/components/banner.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/banner.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  Ref,
  SlotOutlet,
  SlotTemplate,
  agentMember,
  elementRef,
  mountEffect,
  useMember,
  type IconProps,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/banner.module.css'
import { Button, type ButtonProps } from '../controls/Button'

export type BannerTone = NonNullable<BannerProps['tone']>

/** The notice that belongs to the application frame and stays until its cause ends: the inputs it takes, by the React member's prop names. */
export interface BannerProps {
  /**
   * The ✕'s accessible name, default `Dismiss`; localized hosts pass their own.
   */
  dismissLabel?: string
  tone?: 'info' | 'warning' | 'danger' | 'neutral'
}

/** The notice that belongs to the application frame and stays until its cause ends. */
@Component({
  selector: 'pm-banner',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, SlotOutlet, SlotTemplate, Button, Icon],
  // prettier-ignore
  template: `<ng-template pmSlot="action" [pmSlotOf]="$"><ng-content select="[slot=action]" /></ng-template>
<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<div
[attr.class]="e1()"
[attr.role]="e2()"
[attr.data-tone]="e3()"
data-member="banner"
[pmRef]="root"
>@if (e4()) {<!-- glyph -->
<span
[attr.class]="e5()"
><pm-icon
[name]="e6()"
></pm-icon></span>}
<!-- content -->
<div
[attr.class]="e7()"
><!-- text -->
<div
[attr.class]="e8()"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></div>
@if (e9()) {<!-- action -->
<div
[attr.class]="e10()"
><ng-container [pmSlotOutlet]="'action'" [pmSlotOf]="$" /></div>}</div>
@if (e11()) {<!-- close -->
<div
[attr.class]="e12()"
[pmRef]="closeRegion"
><pm-button
variant="ghost"
tone="neutral"
size="sm"
[iconOnly]="e13()"
icon="close"
[label]="e14()"
(click)="h1()"
></pm-button></div>}</div>`,
})
export class Banner {
  /**
   * The ✕'s accessible name, default `Dismiss`; localized hosts pass their own.
   */
  readonly dismissLabel = input<
    Exclude<BannerProps['dismissLabel'], undefined>,
    BannerProps['dismissLabel']
  >('Dismiss', {
    transform: (value: BannerProps['dismissLabel']) => (value === undefined ? 'Dismiss' : value),
  })
  readonly tone = input<Exclude<BannerProps['tone'], undefined>, BannerProps['tone']>('neutral', {
    transform: (value: BannerProps['tone']) => (value === undefined ? 'neutral' : value),
  })
  /**
   * Renders the ✕. The app removes the Banner; it passes this only where hiding it is safe.
   */
  readonly onDismiss = output<void>({ alias: 'dismiss' })
  protected readonly $ = useMember({
    events: ['dismiss'],
    props: { dismissLabel: () => this.dismissLabel(), tone: () => this.tone() },
  })
  protected readonly $p = this.$.props
  protected readonly closeRegion = elementRef<HTMLElement>()
  protected readonly root = elementRef<HTMLElement>()
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
  }

  protected e1() {
    return styles.banner
  }

  protected e2() {
    return this.$p.tone === 'danger' ? 'alert' : 'status'
  }

  protected e3() {
    return this.$p.tone
  }

  protected e4() {
    return this.$p.tone !== 'neutral'
  }

  protected e5() {
    if (!(this.$p.tone !== 'neutral')) return undefined as never
    return styles.glyph
  }

  protected e6(): IconProps['name'] {
    if (!(this.$p.tone !== 'neutral')) return undefined as never
    return this.$p.tone === 'danger' ? 'error' : this.$p.tone === 'warning' ? 'warning' : 'info'
  }

  protected e7() {
    return styles.content
  }

  protected e8() {
    return styles.text
  }

  protected e9() {
    return this.$.filled('action')
  }

  protected e10() {
    if (!this.$.filled('action')) return undefined as never
    return styles.action
  }

  protected e11() {
    return this.$.listening(this.onDismiss, 'onDismiss')
  }

  protected e12() {
    if (!this.$.listening(this.onDismiss, 'onDismiss')) return undefined as never
    return styles.close
  }

  protected e13(): ButtonProps['iconOnly'] {
    if (!this.$.listening(this.onDismiss, 'onDismiss')) return undefined as never
    return true
  }

  protected e14(): ButtonProps['label'] {
    if (!this.$.listening(this.onDismiss, 'onDismiss')) return undefined as never
    return this.$p.dismissLabel
  }

  protected h1(): void {
    if (!this.$.listening(this.onDismiss, 'onDismiss')) return
    this.$.emit(this.onDismiss, 'onDismiss')
  }

  private effect1(): void {
    this.release1?.()
    const ran = agentMember({
      member: 'Banner',
      element: () => this.root.value,
      state: () => ({
        tone: this.$p.tone,
        dismissible: this.$.listening(this.onDismiss, 'onDismiss'),
      }),
      actions: {
        dismiss: () =>
          (() => {
            if (!this.$.listening(this.onDismiss, 'onDismiss'))
              throw new Error('This banner has no dismiss control.')
            this.$.emit(this.onDismiss, 'onDismiss')
          })(),
      },
      withholds: () => this.closeRegion.value,
    })
    this.release1 = () => {
      ran()
    }
  }
}
